// public/sw.js
// This file will be generated by next-pwa during the build process
// But we can add custom event listeners here

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") {
    self.skipWaiting();
  }
});

// Custom fetch handler to provide a fallback for API requests
self.addEventListener("fetch", (event) => {
  // Let workbox handle the default caching behavior
  // Just adding custom fallback logic for API requests

  if (event.request.url.includes("trees.firstasia.edu.ph/api")) {
    event.respondWith(
      fetch(event.request).catch(() => {
        // Return a custom response for failed API requests
        return new Response(
          JSON.stringify({
            success: false,
            message: "You are offline. Please check your internet connection.",
            offline: true,
          }),
          {
            headers: { "Content-Type": "application/json" },
          }
        );
      })
    );
  }
});
